def agg(self, target, tree):
    try:
        avg_acc = tree[self]
    except KeyError:
        avg_acc = tree[self] = [0.0, 0]
    avg_acc[0] += target
    avg_acc[1] += 1
    return avg_acc[0] / avg_acc[1]

class Sum:
    """
    takes the sum of all values;
    raises exception on non-numeric value

    >>> glom([1, 2, 3], Group(Sum()))
    6
    """
    __slots__ = ()

    def agg(self, target, tree):
        if self not in tree:
            tree[self] = 0
        tree[self] += target
        return tree[self]

    def __repr__(self):
        return '%s()' % self.__class__.__name__


class Count:
    """
    counts the number of values

    >>> glom([1, 2, 3], Group(Count()))
    3
    """
    __slots__ = ()

    def agg(self, target, tree):
        if self not in tree:
            tree[self] = 0
        tree[self] += 1
        return tree[self]

    def __repr__(self):
        return '%s()' % self.__class__.__name__
